/// Game-wide constants for Harita: Kendi İmparatorluğunu Kur.
///
/// All magic numbers used across the codebase should be referenced
/// from this file to ensure consistency and ease of configuration.
library;

// ─── Map ────────────────────────────────────────────────────────────────────

/// Total number of cities (regions) on the Africa map.
///
/// Must match `assets/maps/territory_graph.json`, which is generated by
/// `tool/generate_africa_map.py`.
const int kTerritoryCount = 133;

/// Soldiers on the four start cities of a human player ("135, 125, 110").
const List<int> kHumanStartUnits = [135, 125, 120, 110];

/// Cities every bot owns at game start.
const int kBotStartCities = 2;

/// Range of soldiers on a bot's start cities (random, inclusive).
const int kBotStartUnitsMin = 60;
const int kBotStartUnitsMax = 130;

/// Range of soldiers on a neutral city at game start (random, inclusive).
const int kNeutralUnitsMin = 10;
const int kNeutralUnitsMax = 40;

/// How many bots start close to the first player ("benim yakınlarıma 3
/// tane yapay zeka şehir") — two steps away, never right next door.
const int kBotsNearPlayer = 3;

/// Most bots that can join a game (6 + "4 tane daha").
const int kMaxBots = 10;

/// Most human players sharing one device.
const int kMaxHumans = 2;

// ─── Army equipment ─────────────────────────────────────────────────────────

/// Tanks every army starts with.
const int kStartTanks = 5;

/// Bombers every army starts with.
const int kStartBombers = 4;

/// Extra attack strength a tank adds to an attack. Each tank joins one
/// attack per turn; it is destroyed when the attack fails.
const int kTankPower = 25;

/// Soldiers one bomber raid destroys in the target city. Every bomber
/// flies once per turn.
const int kBomberDamage = 15;

/// Defenders in a forest city count this much more.
const double kForestDefenseBonus = 0.25;

// ─── Economy ─────────────────────────────────────────────────────────────────

/// Diamonds (Elmas) every army earns at the end of each of its turns.
const int kDiamondsPerTurn = 80;

/// Diamonds earned for capturing a city with a diamond mine.
const int kDiamondMineReward = 250;

/// Diamonds earned for capturing a gold-mine city (a big capital).
const int kGoldMineReward = 150;

/// Diamonds every army starts the game with.
const int kStartDiamonds = 50;

/// Soldiers every owned city gains at the end of its owner's turn.
const int kCityGrowth = 5;

/// City growth for bots on "Zor" (hard) difficulty.
const int kHardCityGrowth = 7;

/// City growth for bots on "Çok Kolay" (very easy) difficulty.
const int kVeryEasyCityGrowth = 3;

// ─── Cards ("kartlar") ───────────────────────────────────────────────────────

/// Cities each bomb card hits.
const int kFireBombCities = 1;
const int kBombardmentCities = 2;
const int kMegaBombaCities = 3;
const int kAtomBombCities = 4;
const int kNuclearBombCities = 6;

/// Soldiers each bomb card kills in every city it hits. A city left
/// without soldiers is captured.
const int kFireBombDamage = 40;
const int kBombardmentDamage = 40;
const int kMegaBombaDamage = 60;
const int kAtomBombDamage = 80;
const int kNuclearBombDamage = 100;

/// Soldiers left on every city captured by a card.
const int kCapturedCityUnits = 10;

/// Soldiers added to a friendly city by the Soldier Spell.
const int kSoldierSpellUnits = 40;

/// Diamonds the "Haraç Kes" card takes from the target city's owner.
const int kTributeDiamonds = 200;

// ─── Layout breakpoints ──────────────────────────────────────────────────────

/// Screen width (in dp) at or above which the tablet layout is used.
const double kPhoneBreakpoint = 600;

// ─── Animation ───────────────────────────────────────────────────────────────

/// How long the player's soldiers (and tank) march to the target before
/// the battle is fought.
const int kMarchMs = 700;

/// How long a bomber flies to its target.
const int kBomberFlightMs = 800;

// ─── AI ──────────────────────────────────────────────────────────────────────

/// Minimum artificial delay (ms) between AI actions for visual legibility.
const int kAiActionDelayMinMs = 300;

/// Maximum artificial delay (ms) between AI actions for visual legibility.
const int kAiActionDelayMaxMs = 500;

/// Delay (ms) between AI actions once the bot has made many moves in a turn.
const int kAiFastActionDelayMs = 60;

/// Fast delay (ms) used when more than two bots play, so a whole round of
/// up to ten bots stays short.
const int kAiManyBotsFastDelayMs = 25;

/// After this many actions in one turn the bot switches to the fast delay.
const int kAiSlowActionCount = 6;

/// Minimum strength ratio (AI : enemy) required for AI to attack an enemy.
const double kAiAttackOddsThreshold = 1.5;
